f = fcnchk(@sin);
f(0)
g = fcnchk('x^2+1');
g(2)

f = ode(ODEFcn=@(t, y) -y, InitialValue=1);
sol = solve(f, 0, 2);
fprintf('y(2) = %.3f\n', sol.Solution(end))
fprintf('exact  %.3f\n', exp(-2))

e = odeEvent(EventFcn=@(t, y) y - 0.5);
f = ode(ODEFcn=@(t, y) -y, InitialValue=1, EventDefinition=e);
sol = solve(f, 0, 3);
fprintf('%.4f\n', sol.EventTime)
fprintf('%.4f\n', log(2))

J = odeJacobian(Jacobian=@(t, y) -1);
f = ode(ODEFcn=@(t, y) -y, InitialValue=1, Jacobian=J, Solver='ode15s');
sol = solve(f, 0, 1);
fprintf('%.3f\n', sol.Solution(end))

M = odeMassMatrix(MassMatrix=[2 0; 0 1]);
f = ode(ODEFcn=@(t, y) -y, InitialValue=[1; 1], MassMatrix=M);
sol = solve(f, 0, 1);
fprintf('%.4f %.4f\n', sol.Solution(:, end))
fprintf('%.4f %.4f\n', exp(-0.5), exp(-1))

